#include "field_mod.hpp"
#include <array>
using Mon=array<int,9>;
int main(int argc,char**argv){nmod_mpoly_ctx_init(ctx,2,ORD_LEX,prime);{ifstream in(argv[1]);ofstream out(argv[2]);ofstream facts(string(argv[2])+".contents");int nr;in>>nr;vector<int>keep={0,1,2,3,4,6,8};out<<nr<<'\n';fmpq_t cf;fmpq_init(cf);for(int rr=0;rr<nr;rr++){int id,n;in>>id>>n;map<Mon,Rat>row;for(int k=0;k<n;k++){string cs;in>>cs;int m[16];for(int j=0;j<16;j++)in>>m[j];bool bad=false;for(int j=2;j<7;j++)bad|=m[j]!=0;bad|=m[12]!=0||m[14]!=0;if(bad)continue;assert(!fmpq_set_str(cf,cs.c_str(),10));fmpq_canonicalise(cf);ulong a=fmpz_fdiv_ui(fmpq_numref(cf),prime),b=fmpz_fdiv_ui(fmpq_denref(cf),prime);assert(b);ulong c=n_mulmod2_preinv(a,n_invmod(b,prime),prime,n_preinvert_limb(prime));Mon mon{};for(int j=0;j<9;j++)mon[j]=m[7+j];ulong ex[2]={(ulong)m[0],(ulong)m[1]};auto&v=row[mon];ulong old=nmod_mpoly_get_coeff_ui_ui(v.n,ex,ctx);nmod_mpoly_set_coeff_ui_ui(v.n,(old+c)%prime,ex,ctx);}in>>n;for(int k=0;k<n;k++){string cs;int m;in>>cs;for(int j=0;j<16;j++)in>>m;}Rat g,tmp;for(auto&[m,v]:row){assert(nmod_mpoly_gcd(tmp.n,g.n,v.n,ctx));nmod_mpoly_swap(tmp.n,g.n,ctx);}facts<<id<<'\n';writepoly(facts,g.n);out<<id<<' '<<row.size()<<'\n';for(auto&[m,v]:row){assert(nmod_mpoly_divides(tmp.n,v.n,g.n,ctx));for(auto j:keep)out<<m[j]<<' ';out<<'\n';writepoly(out,tmp.n);}cerr<<"row "<<id<<" coefficients "<<row.size()<<" gcddegree "<<nmod_mpoly_total_degree_si(g.n,ctx)<<'\n';}fmpq_clear(cf);}nmod_mpoly_ctx_clear(ctx);flint_cleanup();}
